import unittest

from solucao import e_de_maior


class TestDevolverVerdadeiroOuFalso(unittest.TestCase):
    def test_devolve_true_para_vinte(self):
        """a caixa devolve True para a idade 20"""
        self.assertTrue(e_de_maior(20))

    def test_devolve_false_para_quinze(self):
        """a caixa devolve False para a idade 15"""
        self.assertEqual(e_de_maior(15), False)

    def test_devolve_true_para_dezoito(self):
        """a caixa devolve True para a idade 18"""
        self.assertTrue(e_de_maior(18))
